import sys, re
sys.path.insert(0,'/workspace/work_mito')
from score_orfs import segments, aa_stats, RC_TRANS
p='/workspace/work_mito/flye_sample5000/00-assembly/draft_assembly.fasta'
name=None; s=[]
def emit():
 if name is None:return
 best=None
 for orient,x in [('+',bytes(s)),('-',bytes(s).translate(RC_TRANS)[::-1])]:
  for nt,frame,a,b in segments(x):
   z=aa_stats(nt); key=(z[0]*z[1],z[0])
   if best is None or key>best[0]: best=(key,z,orient+str(frame+1),a,b)
 if best:
  _,z,fr,a,b=best
  print(name, len(s), z[0], f'{z[1]:.3f}', f'{z[2]:.3f}', f'{z[3]:.3f}', z[4], fr,a,b, sep='\\t')
for line in open(p):
 line=line.strip()
 if line.startswith('>'):
  emit();name=line[1:].split()[0];s=[]
 else:s.extend(line.encode().upper())
emit()
