from pathlib import Path
from sys import path
path.insert(0,'/workspace/work_mito')
from find_mt_motifs import translate, CODON, RC_TRANS, MOTIFS
from score_mito_contigs import metrics
for fn in ['unit15449.fa','samtools_consensus_unit.fa']:
 s=''.join(x.strip() for x in Path('/workspace/work_mito/'+fn).read_text().splitlines() if not x.startswith('>')).encode()
 print(fn,len(s),metrics(s),metrics(s.translate(RC_TRANS)[::-1]))
 for ori,x in [('+',s),('-',s.translate(RC_TRANS)[::-1])]:
  for f in range(3):
   aa=translate(x,f)
   hits=[]
   for m in MOTIFS:
    j=aa.find(m.pattern.decode())
    if j>=0:hits.append((m.pattern.decode(),j))
   if hits: print(' ',ori,f,hits)
